{noformat}USE taxify_fleet;
DROP PROCEDURE IF EXISTS upd_in_loop_3139;

DELIMITER $$
CREATE PROCEDURE upd_in_loop_3139()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 500;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 10;
  DECLARE v_sleep_time INT DEFAULT 2;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_fleet`.`driver_scheduled_blocking`;

  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO
  UPDATE `taxify_fleet`.`driver_scheduled_blocking` AS b
            JOIN `taxify_fleet`.`driver_scheduled_blocking_unblock_sync_log` AS ul ON ul.driver_scheduled_blocking_id = b.id
            SET
                b.end = FROM_UNIXTIME(2147483647),
                ul.end = FROM_UNIXTIME(2147483647),
                ul.status = 'not_synced'
            WHERE b.reason IN ('custom', 'incorrect_pricing', 'customer_complaints', 'impersonating_another_driver', 'high_priority_cases')
            AND b.id >= v_min_id
            AND b.id < v_min_id + v_batch_size
            AND b.end > NOW()
            AND b.end < FROM_UNIXTIME(2147483647)
            AND TIMESTAMPDIFF(DAY, b.start, b.end) >= 180;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;

CALL upd_in_loop_3139();

