{{type}} column already has {{takeawy}} enum value

table:

{noformat}`type` enum('regular', 'dispatch_first', 'takeaway') NOT NULL DEFAULT 'regular'{noformat}

your request:

{noformat}`type` ENUM('regular', 'dispatch_first', 'takeaway') NOT NULL DEFAULT 'regular'{noformat}

