The following procedure is going to be used for the batched insert. Please review and approve:

{noformat}USE taxify_company;
DROP PROCEDURE if exists update_in_loop_3489;
DELIMITER $$
CREATE PROCEDURE update_in_loop()
BEGIN
  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 1000;
  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM taxify_company.driver_destination_location;  
  SELECT v_min_id, v_max_id, v_batch_size; 
  WHILE v_min_id <= v_max_id DO
	INSERT INTO taxify_dispatch_pref.driver_destination_location (id, created, driver_destination_id, driver_city_id)
	SELECT id, created, driver_destination_id, driver_city_id FROM taxify_company.driver_destination_location as company
	WHERE company.id >= v_min_id AND company.id < v_min_id + v_batch_size AND company.created < '2020-10-29 00:00:00.000'
	ON DUPLICATE KEY UPDATE id = company.id, created = company.created, driver_destination_id = company.driver_destination_id, driver_city_id = company.driver_city_id;
     SET v_min_id = v_min_id + v_batch_size;
    SELECT v_min_id, v_min_id*100/v_max_id as done;
  END WHILE;
END;
$$
DELIMITER ;
CALL update_in_loop_3489();
DROP PROCEDURE if exists update_in_loop_3489;{noformat}

